import React from 'react';import './Sidebar.css';
const groups=[['WORKSPACE',['Dashboard','Leads','Follow-ups','Customers']],['INVENTORY',['Projects','Properties','Site Visits','Bookings','Payments']],['PEOPLE & HR',['Employees','Attendance','Payroll']],['ENGAGEMENT',['WhatsApp','Reports','Settings']]];
const icons={Dashboard:'▦',Leads:'◉','Follow-ups':'◷',Customers:'♙',Projects:'⌂',Properties:'▤','Site Visits':'⌖',Bookings:'▣',Payments:'₹',Employees:'♧',Attendance:'◷',Payroll:'₹',WhatsApp:'◌',Reports:'▥',Settings:'⚙'};
export default function Sidebar({activePage,onNavigate,collapsed,user}){const ownerOnly=['Payments','Employees','Payroll','Reports','Settings'];const visibleGroups=groups.map(([group,items])=>[group,items.filter(item=>user?.role==='owner'||!ownerOnly.includes(item))]).filter(([,items])=>items.length);return <aside className={`sidebar ${collapsed?'collapsed':''}`}><div className="brand"><div className="brand-logo">R<span>+</span></div>{!collapsed&&<div><b>RealEstate<span>Pro</span></b><small>CRM WORKSPACE</small></div>}</div><div className="workspace"><span className="workspace-logo">NR</span>{!collapsed&&<div><b>Northstar Realty</b><small>Owner workspace</small></div>}</div><nav>{visibleGroups.map(([group,items])=><section key={group}>{!collapsed&&<label>{group}</label>}{items.map(item=><button key={item} title={collapsed?item:''} className={activePage===item?'active':''} onClick={()=>onNavigate(item)}><i>{icons[item]}</i>{!collapsed&&<span>{item}</span>}</button>)}</section>)}</nav><div className="profile"><span>MK</span>{!collapsed&&<div><b>{user?.name || 'CRM User'}</b><small>{user?.role === 'owner' ? 'Owner' : 'Employee'}</small></div>}</div></aside>}
